const productFeedbackList = `-- name: ProductFeedbackList :many
SELECT pf.uuid, pf.kind, pf.message, pf.route, pf.surface, pf.app_version, pf.device, pf.attachment_uuids,
       pf.status, pf.created_at, o.uuid AS organization_uuid, o.name AS organization_name,
       COALESCE(u.email, '')::text AS user_email
FROM product_feedback pf
JOIN organizations o ON o.id = pf.organization_id
LEFT JOIN users u ON u.id = pf.user_id
WHERE ($1::text = '' OR pf.kind = $1::text)
  AND ($2::text = '' OR pf.status = $2::text)
ORDER BY pf.created_at DESC
LIMIT $4 OFFSET $3
`

type ProductFeedbackListParams struct {
	Kind     string `json:"kind"`
	Status   string `json:"status"`
	SkipRows int32  `json:"skip_rows"`
	MaxRows  int32  `json:"max_rows"`
}

type ProductFeedbackListRow struct {
	Uuid             uuid.UUID          `json:"uuid"`
	Kind             string             `json:"kind"`
	Message          string             `json:"message"`
	Route            string             `json:"route"`
	Surface          string             `json:"surface"`
	AppVersion       string             `json:"app_version"`
	Device           string             `json:"device"`
	AttachmentUuids  []uuid.UUID        `json:"attachment_uuids"`
	Status           string             `json:"status"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
	OrganizationUuid uuid.UUID          `json:"organization_uuid"`
	OrganizationName string             `json:"organization_name"`
	UserEmail        string             `json:"user_email"`
}

func (q *Queries) ProductFeedbackList(ctx context.Context, arg ProductFeedbackListParams) ([]ProductFeedbackListRow, error) {
	rows, err := q.db.Query(ctx, productFeedbackList,
		arg.Kind,
		arg.Status,
		arg.SkipRows,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProductFeedbackListRow{}
	for rows.Next() {
		var i ProductFeedbackListRow
		if err := rows.Scan(
			&i.Uuid,
			&i.Kind,
			&i.Message,
			&i.Route,
			&i.Surface,
			&i.AppVersion,
			&i.Device,
			&i.AttachmentUuids,
			&i.Status,
			&i.CreatedAt,
			&i.OrganizationUuid,
			&i.OrganizationName,
			&i.UserEmail,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const productFeedbackSetStatus = `-- name: ProductFeedbackSetStatus :execrows
UPDATE product_feedback SET status = $1 WHERE uuid = $2
`

type ProductFeedbackSetStatusParams struct {
	Status string    `json:"status"`
	Uuid   uuid.UUID `json:"uuid"`
}

func (q *Queries) ProductFeedbackSetStatus(ctx context.Context, arg ProductFeedbackSetStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, productFeedbackSetStatus, arg.Status, arg.Uuid)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
